/**
 * Request side only: HTTP path and the body fields that identify the customer, the card and the week.
 * The ledger lookup does not read this file.
 *
 * Fields are read from body.data (the contract envelope). `call` is ignored.
 * by: "customer" looks up customerNo. "card" finds the customer from the card key.
 */
export const routes = [
  route("cards.list", "customer", "customerNo", "", "", [["customerNo", "customer number"]]),
  route("cards.balance", "card", "", "cardNumber", "", [["cardNumber", "card number"]]),
  route("statement.week.get", "card", "", "cardNumber", "", [["cardNumber", "card number"]]),
  route("statement.week.decide", "card", "", "cardNumber", "newStatementWeek", [
    ["cardNumber", "card number"],
    ["newStatementWeek", "newStatementWeek"],
    ["statementDay", "statementDay"],
  ]),
  route("statement.week.change", "card", "", "cardNumber", "newStatementWeek", [
    ["cardNumber", "card number"],
    ["newStatementWeek", "newStatementWeek"],
    ["statementDay", "statementDay"],
  ]),
  route("contact.email.get", "customer", "customerNo", "", "", [
    ["customerNo", "customer number"],
    ["intAddressInfoType", "intAddressInfoType"],
  ]),
  route("statement.pdf.send", "customer", "customerNo", "cardNumber", "", [
    ["customerNo", "customer number"],
    ["cardNumber", "card number"],
    ["currencyType", "currencyType"],
    ["statementDate", "statement date"],
    ["emailAddress", "email address"],
  ]),
];

function route(service, by, customer, card, week, required) {
  return { method: "POST", path: `/voice/v1/${service}`, service, by, customer, card, week, required };
}

export function match(method, pathname) {
  const path = pathname.startsWith("/v1/") ? "/voice" + pathname : pathname;
  return routes.find((route) => route.method === method && route.path === path) || null;
}

export function take(route, body) {
  const data = body && body.data && typeof body.data === "object" ? body.data : body || {};
  return {
    service: route.service,
    customerNo: route.customer ? data[route.customer] : undefined,
    card: route.card ? data[route.card] : undefined,
    week: route.week ? data[route.week] : undefined,
    data,
  };
}

export function openapi() {
  const paths = {};
  for (const route of routes) {
    const properties = {};
    const required = [];
    for (const [field] of route.required) {
      properties[field] = { type: "string" };
      required.push(field);
    }
    paths[route.path] = {
      post: {
        operationId: route.service,
        requestBody: {
          required: true,
          content: {
            "application/json": {
              schema: {
                type: "object",
                properties: {
                  data: { type: "object", properties, required },
                  call: {
                    type: "object",
                    properties: { ani: { type: "string" }, lang: { type: "string" } },
                  },
                },
                required: ["data"],
              },
            },
          },
        },
        responses: { "200": { description: "Canned test-environment body" } },
      },
    };
  }
  paths["/oauth2/token"] = {
    post: {
      operationId: "oauth2.token",
      responses: { "200": { description: "Bearer token, not checked by the test environment" } },
    },
  };
  return {
    openapi: "3.0.3",
    info: { title: "Freya Bank statement services", version: "bound" },
    paths,
  };
}

