import { answer, customerNoForCard, sampleAnswer } from "./lookup.js";
import { take } from "./routes.js";

const NOT_FOUND = {
  "cards.list": { http: 404, code: "FB_IVR_CHANNEL_102", type: "WARNING", message: "Müşteriye ait geçerli kart bilgisi bulunamadı." },
  "cards.balance": { http: 404, code: "FB_IVR_CHANNEL_120", type: "WARNING", message: "Kart bakiye servisi hatası: kart bulunamadı" },
  "statement.week.get": { http: 404, code: "FB_IVR_CHANNEL_121", type: "WARNING", message: "Kart bulunamadı" },
  "statement.pdf.send": { http: 404, code: "FB_IVR_CHANNEL_107", type: "WARNING", message: "Pdf dokümanı bulunamadı" },
};

export function isTemplateVariable(value) {
  return typeof value === "string" && (value.startsWith("{{") || value.startsWith("%7B%7B"));
}

const ABSENT_OK = {
  "contact.email.get": ["intAddressInfoType"],
  "statement.week.decide": ["statementDay"],
  "statement.week.change": ["statementDay"],
  "statement.pdf.send": ["cardNumber", "currencyType", "statementDate", "emailAddress"],
};

export function handle(doc, route, body) {
  const query = take(route, body);
  const values = [query.customerNo, query.card, query.week, ...route.required.map(([field]) => query.data[field])];
  if (values.some(isTemplateVariable)) {
    const sample = sampleAnswer(doc, route.service);
    if (sample.found) return sample;
  }
  const absentOk = new Set(ABSENT_OK[route.service] || []);
  for (const [field, label] of route.required) {
    const value = query.data[field];
    if ((value === undefined || value === null) && absentOk.has(field)) continue;
    if (value === undefined || value === null || String(value).trim() === "") {
      return reply(400, envelope("INVALID_ARGUMENTS_ERROR", "ERROR", `${label} cannot be empty`));
    }
  }
  let customerNo = query.customerNo;
  if (route.by === "card") {
    customerNo = customerNoForCard(doc, route.service, query.card);
    if (!customerNo) return miss(route.service, "card");
  }
  const row = answer(doc, {
    service: route.service,
    customerNo,
    card: route.by === "card" ? query.card : undefined,
    week: route.week ? query.week : undefined,
  });
  if (!row.found) return miss(route.service, row.reason);
  return row;
}

function miss(service, reason) {
  const known = NOT_FOUND[service];
  if (known && reason !== "week") return reply(known.http, envelope(known.code, known.type, known.message, reason));
  const message = reason === "week" ? "newStatementWeek is not available" : "customer number is not valid";
  return reply(400, envelope("INVALID_ARGUMENTS_ERROR", "ERROR", message, reason));
}

function reply(http, body) {
  return { found: true, http, body, delaySeconds: 0 };
}

function envelope(code, type, message, reason) {
  const guid = hash(`${code}:${reason || ""}:${message}`).padEnd(32, "0").slice(0, 32);
  const rootCause = type === "WARNING" ? "NotFoundException" : "IllegalArgumentException";
  return {
    result: {
      guid,
      returnCode: code,
      messageText: message,
      code,
      message,
      type,
      details: { guid, rootCause, errorOrigin: "ivr-gateway-test:ivr-channel-v0" },
    },
  };
}

function hash(text) {
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) h = Math.imul(h ^ text.charCodeAt(i), 16777619);
  return (h >>> 0).toString(16);
}

