    name = str(raw.get("productName") or "").strip()
    return {
        "number": number,
        "last4": last4,
        "name": name,
        "bin": _bin_of(number),
        "full": "*" not in number and len(re.sub(r"\D", "", number)) >= 15,
        "status": str(raw.get("status") or "A"),
    }


