            vars["week_fail_line"] = WEEK_MONTH
        else:
            vars["week_fail_line"] = WEEK_FAIL
        vars["route"] = "fail"
    except Exception:
        vars["week_fail_line"] = WEEK_FAIL
        vars["route"] = "fail"


def apply_which(vars):
