    try:
        sim_id, it_id, status = freya.run_simulation(agent_id, 'cursor-bank-1-smoke', vars_map, max_seconds=180, concurrency=3)
        print('sim', sim_id, it_id, status)
        it = freya.get_iteration(sim_id, it_id)
        summary = []
        for run in it.get('runs') or []:
            summary.append({
                'persona': run.get('personaId') or run.get('personaName'),
                'outcome': run.get('outcome') or run.get('status'),
                'callId': run.get('callId') or run.get('id'),
