python3 << 'PY'
import json, sys, re
from pathlib import Path
sys.path.insert(0, '/Users/toprakgundogdu/Downloads/build-the-builder')
import freya
c = freya.get_call('a7cd5a0e-9837-4fe0-b4cb-f859101a5162')
msgs = c.get('messages') or []
# extract interesting events
for m in msgs:
    text = str(m.get('content') or m.get('text') or '')
    if any(k in text for k in ('node_enter','route_evaluated','tts','assistant','user','error','debt','say_','offer','email','end_','function_call_complete')):
        # compact
        try:
            ev = json.loads(text)
        except Exception:
            print(text[:200]); continue
        et = ev.get('event')
        if et == 'node_enter':
            print('ENTER', ev.get('node'), 'from', ev.get('from_node'))
        elif et == 'route_evaluated':
            print('ROUTE', ev.get('from_node'), '->', ev.get('target'), ev.get('reason'))
        elif et == 'function_call_complete':
            res = ev.get('result') or {}
            data = res.get('data')
            print('FUNC', ev.get('function'), 'status', res.get('status'), 'keys', list(data)[:8] if isinstance(data, dict) else type(data))
            if ev.get('function')=='api_call' and isinstance(data, dict):
                # show nested
                print('  data sample', str(data)[:250])
        elif et in ('tts','assistant_message','message'):
            print('TTS', str(ev)[:200])
        else:
            print(et, str(ev)[:180])
# also look for role user/assistant
for m in msgs:
    role = m.get('role')
    if role in ('user','assistant','agent'):
        print('ROLE', role, str(m.get('content') or m.get('text'))[:250])
# dump last 5 raw
print('--- last 5 ---')
for m in msgs[-5:]:
    print(str(m)[:300])
Path('call-happy.json').write_text(json.dumps(c, ensure_ascii=False, indent=1)[:200000])
print('saved')
PY

